const ARTICLES = [
  {id:1, cat:"delhii", title:"Испанид хурдны хоёр галт тэрэг мөргөлдөж, 68 хүн амиа алдлаа", titleEn:"Two high-speed trains collide in Spain, killing 68 people", time:"30 мин", timeEn:"30 min", img:"https://commons.wikimedia.org/wiki/Special:FilePath/High_speed_Renfe_9671_91-30_016_-9_at_Barcelona_pic1.JPG?width=1000", text:"Испанийн төв нутгийн Толедо мужийн Урда хотын ойролцоо лхагва гарагийн өглөө хурдны хоёр галт тэрэг мөргөлдөж, дор хаяж 68 хүн амиа алдлаа. Мадрид—Севилья чиглэлийн хурдны замд зорчиж явсан Renfe компанийн галт тэрэг улаан гэрлэн дохиотой байсан ч хөдлөх зөвшөөрөл авсны дараа урд нь зогсож байсан Iryo компанийн галт тэрэгт мөргөсөн байна. Тээврийн сайд Оскар Пуэнтегийн мэдэгдсэнээр, компьютерын холбооны доголдлоос болж улаан дохио асч, хөдөлгөөнийг автоматаар зогсоосон ч дараа нь галт тэргийг дахин хөдөлгөх буруу шийдвэр гарчээ.\n\nАврах багийнхан эвдэрсэн вагонуудыг нэг бүрчлэн шалгаж байгаа бөгөөд харанхуй болсон хойно ч хохирогчдын тоо нэмэгдэж болзошгүй гэж бүс нутгийн удирдлага мэдэгдсэн байна. Ерөнхий сайд Педро Санчес ослын газрын ойролцоогоос телевизээр үг хэлж, «Испани даяар гашуудаж байна» гэж онцлоод, мөрдөн шалгалтаар илэрсэн аливаа дутагдлыг арилгана гэж амлав. Тэрбээр аравдугаар сарын 29-нээс 31-нийг хүртэл гурван өдрийн үндэсний гашуудал зарлажээ. Сөрөг хүчний Ардын нам ч 11 дүгээр сард болох сонгуулийн өмнөх сурталчилгааны арга хэмжээнүүдээ цуцалсан байна.\n\nЭнэ нь Испанид энэ онд гарсан хоёр дахь ноцтой төмөр замын осол юм. Нэгдүгээр сард мөн энэ шугам дээр, мөн компаниудын галт тэрэгнүүд оролцсон ослоор 46 хүн амиа алдсан билээ. Тусгаар тогтносон төмөр замын ослын комисс, шүүх, төмөр замын удирдлагууд хоёр осол хоорондоо холбоотой эсэхийг тогтоохоор ажиллаж байна. Санчес «Испани шиг улс нэг жилд хоёр хурдны галт тэрэгний осолд өртөх нь байж боломгүй» гэж хэлж, өндөр хурдны төмөр замын системд итгэх итгэлийг сэргээхийн тулд аюулгүй байдлыг улам чангатгана гэж мэдэгдлээ. Энэ осол нь 2013 онд Сантьяго-де-Компостелад 80 хүн амиа алдсан ослоос хойших Европ дахь хамгийн их хохиролтой төмөр замын осол болж байна.", textEn:"At least 68 people have died after two high-speed trains collided near the town of Urda in Spain's central Toledo province on Wednesday morning. A Renfe high-speed train travelling on the Madrid–Seville line was authorised to proceed despite an active red signal and then struck an Iryo train standing ahead of it. Transport Minister Oscar Puente said the red signal had been triggered by a computer communications failure that automatically halted traffic, but an erroneous decision was then taken to restart the Renfe train.\n\nRescue teams are working through the mangled carriages one by one, and regional authorities have warned the death toll could still rise. Prime Minister Pedro Sanchez, speaking on television from near the scene, said all of Spain was in mourning and promised to address any failures the investigation uncovers. He declared three days of national mourning from October 29 to 31. The opposition People's Party also cancelled campaign events ahead of an election in November.\n\nThis is Spain's second major rail disaster this year. In January, 46 people died in an accident on the same line involving trains operated by the same companies. The Independent Railway Accident Commission, the courts and railway authorities are now examining whether the two crashes are connected. Sanchez said it was unacceptable for a country like Spain to suffer two high-speed rail accidents in one year and pledged to strengthen safety to rebuild confidence in the system. The crash is Europe's deadliest rail accident since the 2013 derailment in Santiago de Compostela, which killed 80 people."},
  {id:2, cat:"delhii", title:"Хойд Солонгос зүүн тэнгис рүү 10 орчим богино зайн пуужин харвав", titleEn:"North Korea fires around 10 short-range ballistic missiles towards the East Sea", time:"1 цаг", timeEn:"1 hour ago", img:"https://commons.wikimedia.org/wiki/Special:FilePath/North_Korea%27s_ballistic_missile_-_North_Korea_Victory_Day-2013_01.jpg?width=760", text:"Хойд Солонгос пүрэв гарагийн үд дунд зүүн эргийн Вонсан орчмоос 10 орчим богино зайн баллистик пуужин харвасан гэж Өмнөд Солонгосын Жанжин штабын дарга нарын нэгдсэн хороо мэдээллээ. Пуужингууд орон нутгийн цагаар 12:30 цагийн орчим хөөрч, 250 орчим километр нисч, Япон тэнгист унасан байна. Японы Батлан хамгаалах яам пуужин Японы онцгой эдийн засгийн бүсэд унаагүй гэж мэдэгдсэн бөгөөд хөлөг онгоцонд хохирол учраагүй гэж Японы эргийн хамгаалалт мэдээлжээ.\n\nӨмнөд Солонгосын Ерөнхийлөгчийн Үндэсний аюулгүй байдлын газар яаралтай хуралдаж, хөөргөлтийг НҮБ-ын Аюулгүй байдлын зөвлөлийн тогтоолуудыг «ноцтой зөрчсөн» хэрэг гэж нэрлээд, зогсоохыг уриаллаа. Сөүл тандалтыг эрчимжүүлж, АНУ, Японтой мэдээллээ нягт солилцож байна. Энэ нь энэ сарын гурав дахь хөөргөлт бөгөөд өмнөх нь аравдугаар сарын 12-нд Пхеньян орчмоос хийгдэж, зарим пуужин нь 900 гаруй километр ниссэн билээ.\n\nХурцадмал байдал есдүгээр сарын 21-нд цэрэггүй бүсэд болсон хоёр мина дэлбэрэлтээр гурван Өмнөд Солонгос цэрэг шархадсаны дараа эрс нэмэгдсэн юм. Өмнөд Солонгос, НҮБ-ын хамтарсан шалгалтаар минаг Хойд Солонгос нэг жилийн өмнө суулгасан гэж дүгнэсэн бол Пхеньян үүнийг няцааж, Сөүлийг дэлбэрэлтийг зохиосон гэж буруутгаж байна. Сөүл аравдугаар сарын 23-нд цэргийн хэлэлцээ хийхийг санал болгосон ч Пхеньян одоогоор хариу өгөөгүй бөгөөд Ким Жон Уны эгч Ким Ё Жон хилийн дагуу Өмнөд Солонгосын эсрэг суртал ухуулгын чанга яригч ажиллуулна гэж сүрдүүлсэн билээ.", textEn:"North Korea fired around 10 short-range ballistic missiles from the area around Wonsan on its east coast at midday on Thursday, South Korea's Joint Chiefs of Staff said. The missiles were launched at about 12:30 p.m. local time, flew roughly 250 kilometres and fell into the Sea of Japan. Japan's Defence Ministry said the missiles did not appear to have landed within Japan's exclusive economic zone, and Japan's Coast Guard said no damage to vessels had been confirmed.\n\nSouth Korea's presidential National Security Office held an emergency meeting, calling the launches a serious violation of UN Security Council resolutions and urging Pyongyang to stop. Seoul has stepped up surveillance and is sharing information closely with the United States and Japan. It was the third launch this month; the previous one, on October 12 from the Pyongyang area, saw some missiles travel more than 900 kilometres.\n\nTensions have risen sharply since two landmine explosions in the Demilitarised Zone on September 21 wounded three South Korean soldiers. A joint South Korea–United Nations investigation concluded that North Korea had planted the mines more than a year ago, but Pyongyang rejected the finding and accused Seoul of fabricating the blasts. Seoul proposed military talks on October 23, but Pyongyang has not responded, and Kim Yo Jong, the sister of leader Kim Jong Un, has threatened to activate propaganda loudspeakers along the border."},
  {id:3, cat:"delhii", title:"Израилын сонгуулийн эцсийн дүнд Нетаньяхугийн эвсэл олонх бүрдүүлж чадсангүй", titleEn:"Netanyahu's bloc falls short of majority as Israel election count ends", time:"2 цаг", timeEn:"2 hours ago", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Knesset_Building_(South_Side).JPG?width=760", text:"Израилын сонгуулийн санал тооллого дуусч, Ерөнхий сайд Биньямин Нетаньяхугийн эвсэл парламентад олонх бүрдүүлж чадаагүй нь тодорхой боллоо. Ликуд нам хамгийн олон санал авсан ганц нам хэвээр байгаа ч 120 суудалтай Кнессетэд засгийн газар байгуулахад шаардлагатай 61 суудлыг эвсэл нь бүрдүүлж чадахгүй байгаа бөгөөд Араб тэргүүтэй намууд байр сууриа бэхжүүлсэн байна. Ингэснээр эвслийн хэлэлцээ долоо хоногоор сунжрах төлөвтэй байна.\n\nНетаньяху сонгуулийг «хулгайлагдсан» гэж мэдэгдэж, Араб тэргүүтэй намуудыг сонгуулийн луйвар хийсэн гэж буруутгасан бөгөөд түүний мэдэгдэлд баримт нотолгоо дутмаг гэж шүүмжлэгчид үзэж байна. Сонгуулийн дээд байгууллага дотоодын аюулгүй байдлын агентлагаас гадаадын оролцоо байж болзошгүй гэх мэдэгдлийг шалгахыг хүссэн билээ. Ажиглагчид Ликуд хамгийн том нам хэвээр байгаа нь дангаараа засгийн газар байгуулж чадна гэсэн баталгаа болохгүй гэж онцолж байна.\n\nЭнэ сонгууль нь 2023 оны аравдугаар сарын 7-ны халдлагаас хойшхи анхны улсын сонгууль бөгөөд сонгогчдын идэвх сүүлийн хэдэн арван жилийн хамгийн өндөр түвшинд хүрсэн гэж мэдээлжээ. Сонгууль нь тус улсын хамгийн удаан хугацаанд Ерөнхий сайдаар ажиллаж буй Нетаньяхугийн хувьд итгэл үзүүлэлтийн санал хураалт гэж өргөнөөр харж байв. Албан ёсны баталгаажсан дүн арваннэгдүгээр сарын 4-нд нийтлэгдэж, түүнээс хойш Ерөнхийлөгч засгийн газар байгуулах үүргийг аль нэг намын даргад өгөх юм.", textEn:"Vote counting has ended in Israel's election, leaving Prime Minister Benjamin Netanyahu's bloc short of a parliamentary majority. Likud remains the largest single party, but its bloc cannot reach the 61 seats needed to govern in the 120-seat Knesset, while Arab-led parties have strengthened their position. Coalition talks are now expected to drag on for weeks.\n\nNetanyahu has claimed the election was stolen and accused Arab-led parties of fraud, claims critics say lack evidence. The top electoral body has asked the internal security agency to examine allegations of possible foreign interference. Observers note that Likud being the largest party does not guarantee it can form a government.\n\nThe election was the first national vote since the October 7, 2023 attack, and voter turnout was reported to be among the highest in decades. The vote was widely seen as a referendum on Netanyahu, the country's longest-serving prime minister. Official certified results will be published on November 4, after which the President will task a party leader with forming a government."},
  {id:4, cat:"delhii", title:"G20-гийн Гадаад хэргийн сайд нар Атлантад Украин, Ираны дайны асуудлаар хэлэлцэв", titleEn:"G20 foreign ministers meet in Atlanta for talks dominated by Ukraine and Iran wars", time:"3 цаг", timeEn:"3 hours ago", img:"https://commons.wikimedia.org/wiki/Special:FilePath/G20_South_Africa_leaders_photo_000186343.jpg?width=760", text:"АНУ-ын Төрийн нарийн бичгийн дарга Марко Рубио Атлантад G20-гийн Гадаад хэргийн сайд нарыг хүлээн авч, Украин, Ираны дайн болон өсөж буй эрчим хүчний үнийн асуудлаар хүнд хэцүү хэлэлцээ хийлээ. Уулзалтад Оросын Гадаад хэргийн сайд Сергей Лавров оролцсон бөгөөд энэ нь арванхоёрдугаар сард болох удирдагчдын дээд хэмжээний уулзалтын өмнөх бэлтгэл уулзалт юм.\n\nХэлэлцээний гол сэдэв нь Украинд үргэлжилж буй дайн, Ирантай холбоотой хурцадмал байдал, дэлхийн эрчим хүчний зах зээлд үзүүлж буй дарамт байв. G20 нь дэлхийн хамгийн том эдийн засагтай орнуудыг нэгтгэдэг бөгөөд гишүүн орнуудын хооронд эдгээр асуудлаар байр суурь эрс зөрж байгаа нь хамтарсан мэдэгдэл гаргахад хүндрэл учруулж байна.\n\nАтлантын уулзалт нь удирдагчдын дээд хэмжээний уулзалтын өмнө талуудын байр суурийг тодруулах, яриа хэлэлцээний сувгийг нээлттэй байлгах зорилготой байв. Хэдийгээр томоохон тохиролцоонд хүрсэн тухай мэдээлэл гараагүй ч талууд шууд ярилцсан нь өөрөө дипломат ач холбогдолтой гэж ажиглагчид үзэж байна. Дэлхийн эдийн засгийн өсөлт, худалдаа, эрчим хүчний аюулгүй байдал зэрэг асуудлууд дээд хэмжээний уулзалтын хэлэлцэх асуудлын жагсаалтад хэвээр байна.", textEn:"US Secretary of State Marco Rubio hosted his G20 counterparts in Atlanta, including Russia's Sergei Lavrov, for difficult talks dominated by the wars in Ukraine and Iran and rising energy prices, ahead of the leaders' summit in December.\n\nThe main topics were the continuing war in Ukraine, tensions involving Iran and the pressure on global energy markets. The G20 brings together the world's largest economies, and sharp differences among members on these issues are complicating efforts to agree joint statements.\n\nThe Atlanta meeting was intended to clarify positions and keep channels of dialogue open before the leaders' summit. No major breakthrough was reported, but observers said the fact that the sides talked directly carried diplomatic significance in itself. Global economic growth, trade and energy security remain on the agenda for the summit."},
  {id:5, cat:"delhii", title:"Хормузын хоолойд газрын тос тээвэрлэгч гурван хөлөг шатаж, дэлбэрлээ", titleEn:"Three oil tankers catch fire and explode near the Strait of Hormuz", time:"4 цаг", timeEn:"4 hours ago", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Oil_tanker%2C_gas_tanker_in_the_high_sea_Refinery_Industry_cargo_ship_(52848038105).jpg?width=760", text:"Ираны Хувьсгалт гвардийн тэнгисийн цэргийн мэдэгдсэнээр, Хормузын хоолойгоор зөвшөөрөлгүй замаар явахыг оролдсон газрын тос тээвэрлэгч гурван хөлөг шатаж, дэлбэрсэн байна. Энэ явдал нь дэлхийн эрчим хүчний тээвэрлэлт дэх хурцадмал байдлыг улам нэмэгдүүлж, газрын тосны зах зээлд санаа зовоосон асуудал үүсгэж байна.\n\nХормузын хоолой нь Персийн булангаас дэлхийн зах зээлд газрын тос гаргах хамгийн чухал гарц бөгөөд өдөр бүр асар их хэмжээний газрын тос энэ нарийн усан замаар дамждаг. Тиймээс хоолойд гарсан аливаа осол, мөргөлдөөн нь нийлүүлэлтийн тасалдал үүсгэж болзошгүй гэж ажиглагчид анхааруулж байна.\n\nОдоогоор хөлгүүдийн далбаа, ачаа, багийн гишүүдийн нөхцөл байдлын талаар дэлгэрэнгүй мэдээлэл хязгаарлагдмал байгаа бөгөөд ослын шалтгааныг тогтоох ажил үргэлжилж байна. Бүс нутагт хурцадмал байдал өндөр байгаа үед болсон энэ явдал нь тээврийн компаниуд болон даатгагчдын анхаарлыг татаж, хоолойгоор дамжих тээвэрлэлтийн аюулгүй байдлын талаарх маргааныг дахин сэдрээж байна.", textEn:"Iran's Revolutionary Guards Navy said three oil tankers caught fire and exploded while trying to use what it called unauthorised routes through the Strait of Hormuz, adding to tension in global energy shipping.\n\nThe Strait of Hormuz is the most important passage for oil from the Persian Gulf to world markets, with vast volumes of crude passing through the narrow waterway every day. Observers warn that any incident or confrontation there risks disrupting supplies.\n\nDetails about the tankers' flags, cargoes and crews remain limited so far, and work to establish the cause of the incident is continuing. Coming at a time of high regional tension, the episode has drawn the attention of shipping companies and insurers and has revived debate about the safety of transit through the strait."},
  {id:6, cat:"delhii", title:"Бутаны мөстлөгийн нуурын дэлбэрэлтээс болж Энэтхэгт 12,000 гаруй хүн нүүлгэн шилжүүллээ", titleEn:"Bhutan glacial lake outburst triggers evacuations of more than 12,000 people in India", time:"5 цаг", timeEn:"5 hours ago", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Paro_Taktsang%2C_Bhutan_(edited).jpg?width=760", text:"Бутаны Гаса дүүргийн Шинтафу нууранд аравдугаар сарын 29-нд мөстлөгийн нуурын дэлбэрэлт буюу GLOF болсны дараа Энэтхэгийн хойд хэсэгт Санкош голын дагуу өндөржүүлсэн бэлэн байдал зарлаж, олон мянган хүнийг нүүлгэн шилжүүллээ. Баруун Бенгал мужид дангаараа 12,000 гаруй хүнийг голын усны түвшин нэмэгдсэнтэй холбоотойгоор нүүлгэн шилжүүлсэн гэж мэдээлж байна.\n\nГамшгаас хамгаалах багууд нөлөөлөлд өртсөн бүс нутагт ажиллаж, голын дагуух оршин суугчдад анхааруулга хүргэж байна. Ассам мужид ч мөн өндөржүүлсэн бэлэн байдал зарлагдсан бөгөөд эрх баригчид усны түвшинг тогтмол хянаж байна. Мөстлөгийн нуурын дэлбэрэлт нь уулын мөсөн гол хайлж, нуур үүсч, түүний далан гэнэт задарснаар үүсдэг бөгөөд доош чиглэсэн хөндийгүүдэд гэнэтийн үер үүсгэдэг.\n\nУур амьсгалын өөрчлөлтөөс болж Гималайн мөсөн голууд хурдацтай хайлж байгаа нь ийм эрсдэлийг нэмэгдүүлж байна гэж мэргэжилтнүүд анхааруулж байна. Бутан болон хөрш орнуудын эрх баригчид мөстлөгийн нууруудыг хянаж, эрт сэрэмжлүүлэх системийг сайжруулах чиглэлээр ажиллаж байгаа боловч алслагдсан уулархаг бүс нутагт эрсдэлийг бүрэн арилгах нь хүндрэлтэй хэвээр байна.", textEn:"A glacial lake outburst at Shintaphu Lake in Bhutan's Gasa district on October 29 triggered high flood alerts and the evacuation of thousands of people along India's Sankosh River. In West Bengal alone, more than 12,000 people were evacuated as the river's water level rose.\n\nDisaster response teams have mobilised in the affected areas and are warning residents along the river, while the state of Assam is also on high alert and authorities are monitoring water levels continuously. A glacial lake outburst flood occurs when a lake formed by a melting glacier suddenly breaches its dam, sending a surge of water down the valley.\n\nExperts warn that rapid glacier melt in the Himalayas driven by climate change is increasing such risks. Authorities in Bhutan and neighbouring countries are monitoring glacial lakes and working to improve early warning systems, but fully eliminating the danger in remote mountain areas remains difficult."},
  {id:7, cat:"uls-tor", title:"Ерөнхий сайд Н.Учрал Их Британийн Элчин сайд Эдвин Самуэлийг хүлээн авч уулзав", titleEn:"PM Uchral receives UK Ambassador Edwin Samuel", time:"6 цаг", timeEn:"6 hours ago", img:"https://commons.wikimedia.org/wiki/Special:FilePath/City_building_ulaanbaatar_mongolia.jpg?width=760", text:"Монгол Улсын Ерөнхий сайд Н.Учрал Их Британи, Умард Ирландын Нэгдсэн Хаант Улсаас Монгол Улсад суугаа Элчин сайд Эдвин Самуэлийг хүлээн авч уулзлаа. Элчин сайд Самуэл өнгөрсөн наймдугаар сард Ерөнхийлөгч У.Хүрэлсүхэд Итгэмжлэх жуух бичгээ барьж, үүрэгт ажлаа эхлүүлээд байгаа юм.\n\nЕрөнхий сайд Учрал Монгол Улс «гуравдагч хөрш» Британи Улстай хөгжүүлж буй харилцаа, хамтын ажиллагаанд ач холбогдол өгдгийг тэмдэглэж, манай талаас санаачилсан «Түншлэл, хамтын ажиллагааны хэлэлцээр»-ийг байгуулах чиглэлээр талууд идэвхтэй ажиллахын чухлыг онцлов. Тэрбээр боловсролын салбарын хамтын ажиллагааг өргөжүүлэх, тэр дундаа Кембрижийн хөтөлбөртэй ерөнхий боловсролын сургуулиудын тоог нэмэгдүүлэхэд Британийн талын дэмжлэг чухал гэж тэмдэглэв.\n\nМонгол Улсын Засгийн газар ирэх онд зургаан бүс, нийслэлийн зургаан дүүрэгт олон улсын хөтөлбөртэй нийт 12 ахлах сургууль байгуулахаар төлөвлөж, санхүүжилтийг 2027 оны улсын төсвийн төсөлд тусгаад байна. Элчин сайд Самуэл хоёр орны харилцаа, хамтын ажиллагааг өргөжүүлэхэд бүх талаар дэмжлэг үзүүлж, хамтын ажиллагааны бодит үр дүнг нэмэгдүүлэхийн төлөө ажиллахаа илэрхийлэв.", textEn:"Mongolian Prime Minister Nyam-Osor Uchral received Edwin Samuel, Ambassador of the United Kingdom of Great Britain and Northern Ireland to Mongolia. Ambassador Samuel presented his credentials to President Ukhnaa Khurelsukh last August and has since taken up his duties.\n\nPrime Minister Uchral stressed that Mongolia attaches importance to its relations with the United Kingdom as a third neighbour and emphasised that both sides should work actively towards concluding the Partnership and Cooperation Agreement initiated by Mongolia. He also noted that British support is important for expanding cooperation in education, including increasing the number of general education schools offering the Cambridge programme.\n\nThe Mongolian government plans to establish 12 senior schools with international programmes next year, six in the regions and six in districts of the capital, with funding included in the draft 2027 state budget. Ambassador Samuel said he would support expanding bilateral relations and cooperation in every way and work to increase their tangible results."},
  {id:8, cat:"uls-tor", title:"УИХ төсвийн зарлагыг ил тод болгох хуулийн төслийг дэмжсэнгүй", titleEn:"Parliament rejects bill to make government spending more transparent", time:"7 цаг", timeEn:"7 hours ago", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Mongolia_Parliament_Building.JPG?width=760", text:"Монгол Улсын Их Хурал аравдугаар сарын 23-нд төрийн зарлагыг илүү ил тод болгох тухай хуулийн төслийг хэлэлцэхээс татгалзлаа. Уг хуулийн төслийг гишүүн С.Цэнгүүн болон 30 хамтран санаачлагч өргөн барьсан бөгөөд төрийн хөрөнгө оруулалтын төсөл сонгох шалгуурыг тодорхой болгож, иргэдэд татварын мөнгө хэрхэн зарцуулагдаж буйг харах боломжийг өргөжүүлэх зорилготой байв.\n\nСанал хураалтад бүртгэгдсэн 90 гишүүний 38 нь хуулийн төслийг хэлэлцэхийг дэмжсэн бол 52 нь эсрэг санал өгчээ. Маргаан нь Цэнгүүн хуулийн төслийг анх дэмжиж байсан зарим улс төрч дараа нь намын заавраар эсрэг санал өгсөн гэж мэдэгдсэнээр улам хурцадсан байна. Хуулийн төслийн албан ёсны хамтран санаачлагчдын жагсаалтыг санал хураалтын дүнтэй харьцуулахад долоон хамтран санаачлагч эсрэг баганад бүртгэгдсэн нь тогтоогджээ.\n\nГэхдээ парламентын журмын дагуу бүртгүүлсний дараа оролцоогүй тохиолдол заримдаа сөрөг санал гэж бүртгэгддэг тул зөвхөн энэ баримтаар хүн бүрийг санаатайгаар эсрэг санал өгсөн гэж дүгнэх боломжгүй гэж ажиглагчид тэмдэглэж байна. Олон улсын байгууллагууд Монгол Улсад сонгуулийн баталгаа, төсвийн ил тод байдал, төрийн өмчийн хөрөнгийн хяналтыг бэхжүүлэхийг удаа дараа уриалж ирсэн бөгөөд Нээлттэй Засгийн газрын түншлэлийн үнэлгээнд Монгол Улсын төсвийн ил тод байдлын үзүүлэлт 2017 оноос хойш мэдэгдэхүйц сайжирсан гэж дурджээ.", textEn:"Mongolia's parliament on October 23 rejected a proposal to make government spending more transparent. The bill, introduced by lawmaker S. Tsenguun and 30 co-sponsors, sought to require more detailed disclosure of public expenditure, establish clearer criteria for selecting investment projects and give citizens greater visibility into how their taxes are allocated.\n\nOf the 90 lawmakers recorded in the vote, 38 supported advancing the bill while 52 were recorded against it. The controversy intensified after Tsenguun alleged that some politicians who had supported introducing the bill later opposed its consideration, in certain cases because of party instructions. A comparison of the bill's official sponsorship list with the voting breakdown places seven co-sponsors in the opposing column.\n\nHowever, observers note that under Mongolia's parliamentary procedures, certain failures to participate after registering can be recorded as negative votes, so the record alone cannot establish that each deliberately voted against the proposal. International institutions have repeatedly urged Mongolia to strengthen electoral safeguards, fiscal transparency and oversight of state-controlled assets, while the Open Government Partnership has noted that Mongolia's budget disclosure score has improved substantially since 2017."},
  {id:9, cat:"niigem", title:"Маргааш нутгийн хойд хэсгээр цас орж, говь, тал, хээрийн нутгаар салхи шуургатай байна", titleEn:"Snowstorm in the north and strong winds in the Gobi and steppe expected tomorrow", time:"8 цаг", timeEn:"8 hours ago", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Mongolia_Winter_(127750833).jpeg?width=760", text:"Цаг уур, орчны шинжилгээний газраас аравдугаар сарын 31-нд нутгийн хойд хэсгээр цас орж, цасан шуурга шуурч, говь, тал, хээрийн нутгаар салхитай байхыг анхаарууллаа. 31-ний өдөр баруун аймгуудын нутгийн зүүн хэсэг, төв болон зүүн аймгуудын ихэнх нутаг, говийн аймгуудын нутгийн хойд хэсгээр 0.0–5.0 мм цас орж, цасан шуурга шуурна гэж урьдчилсан мэдээнд дурджээ.\n\nСалхи ихэнх хугацаанд ихэнх нутгаар секундэд 6–11 метр, говь, тал, хээрийн нутгаар секундэд 15–17 метр хүрч ширүүсэж, Алтайн уулархаг нутагт түр зуур секундэд 18–20 метр хүрч, шороон шуурга шуурна. Шөнөдөө Монгол-Алтай, Хэнтийн уулархаг нутаг, Заг-Байдраг голын эх, Онон, Улз, Халх голын хөндийгөөр 14–19 хэм хүйтэн, бусад нутгаар 3–8 хэм хүйтэн байх бол өдөртөө ихэнх нутгаар 2 хэм хүйтнээс 3 хэм дулаан байна.\n\nУлаанбаатар хот орчмоор үүлшинэ. Шөнөдөө цас орохгүй, өдөртөө цас орно. Салхи баруун өмнөөс хойш эргэж секундэд 6–11 метр байна. Шөнөдөө Яармаг-Сонгины орчмоор 9–11 хэм, бусад хэсгээр 5–7 хэм хүйтэн байх бол өдөртөө 2 хэм хүйтнээс 3 хэм дулаан байна. Ойрын 10 хоногийн төлөвөөр Улаанбаатарт 11 дүгээр сарын 4-нд дахин бага зэргийн цас орж, зөөлөн цасан шуурга шуурна гэж Цаг уурын байгууллага мэдээллээ. Малчид, иргэд, тээвэрчдийг цаг агаарын сэрэмжлүүлгийг анхаарч, замд гарахдаа бэлтгэлтэй байхыг зөвлөж байна.", textEn:"The National Agency for Meteorology and Environmental Monitoring has warned that snow and blizzards will hit the northern regions on October 31, with strong winds across the Gobi, steppe and plains. On the 31st, 0.0–5.0 mm of snow is expected in the eastern parts of the western provinces, most of the central and eastern provinces and the northern parts of the Gobi provinces, accompanied by snowstorms.\n\nWinds will mostly reach 6–11 metres per second, strengthening to 15–17 metres per second in the Gobi, steppe and plains, and gusting to 18–20 metres per second in the Altai mountains, where dust storms are possible. Night temperatures will fall to minus 14–19 degrees in the Mongol-Altai and Khentii mountains, the headwaters of the Zag-Baidrag river and the valleys of the Onon, Ulz and Khalkh rivers, and to minus 3–8 degrees elsewhere, while daytime temperatures will mostly range from minus 2 to plus 3 degrees.\n\nIn Ulaanbaatar it will be cloudy, with no snow at night but snow during the day, and winds from the southwest turning north at 6–11 metres per second. Night temperatures will be minus 9–11 degrees around Yarmag-Songino and minus 5–7 degrees elsewhere. The 10-day outlook also predicts light snow and a mild snowstorm in the capital on November 4. Herders, residents and drivers are advised to heed the warnings and prepare before travelling."},
  {id:10, cat:"ediin-zasag", title:"Монголбанк бодлогын хүүгээ 12.5 хувьд хэвээр үлдээж, Засгийн газар Оюутолгойн гэрээг өөрчлөхөөр тохирлоо", titleEn:"Bank of Mongolia holds rate at 12.5%; government and Rio Tinto agree to amend Oyu Tolgoi contract", time:"9 цаг", timeEn:"9 hours ago", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Oyu_Tolgoi_07.JPG?width=760", text:"Монголбанк бодлогын хүүгээ 12.5 хувьд хэвээр үлдээсэн бол Засгийн газар болон Рио Тинто компани Оюутолгойн гэрээг өөрчлөхөөр тохиролцож, Монгол Улсын хүртэх өгөөжийг 13 их наяд төгрөгөөр нэмэгдүүлэхээр болсон гэж салбарын мэдээнд дурджээ. Улсын Их Хурлын намрын чуулган мөн нээлтээ хийж, УИХ-ын дарга Б.Сандаг хууль тогтоох байгууллагын итгэлийг нэмэгдүүлэх, иргэн төвтэй хууль батлах зорилтыг онцолсон байна.\n\nОюутолгойн гэрээний өөрчлөлт нь Монгол Улсын уул уурхайн салбарын хамгийн том төслийн үр өгөөжийг нэмэгдүүлэх чухал алхам гэж үзэж байна. Уул уурхайн долоо хоног, MinePro 2026 арга хэмжээний үеэр ногоон өсөлт, дэлхийн түншлэлийн асуудал гол сэдэв болсон бөгөөд Ерөнхий сайд Н.Учрал, Аж үйлдвэр, эрдэс баялгийн сайд Г.Дамдинням нар эрдэс баялгийн хөгжил нь орон нутгийн иргэдэд бодит үр өгөөж авчрах ёстой гэж онцолсон байна.\n\nМөн Европын сэргээн босголт, хөгжлийн банк болон Ногоон уур амьсгалын сангаас Монголын санхүүгийн системийг ногооруулах GEFF хөтөлбөрийг эхлүүлсэн нь ногоон санхүүжилтийг өргөжүүлэхэд чиглэж байна. Эрдэс баялгийн тухай хуульд оруулах нэмэлт өөрчлөлтүүд парламентын батлах шатанд хүрсэн бөгөөд хайгуул, хөрөнгө оруулалтын нөхцөлийг сайжруулах төлөвтэй байна гэж сайд Дамдинням мэдэгдлээ.", textEn:"The Bank of Mongolia has kept its policy rate unchanged at 12.5 percent, while the government and Rio Tinto have agreed to amend the Oyu Tolgoi contract, increasing Mongolia's returns by 13 trillion tugrik, according to industry news. Parliament's autumn session has also opened, with Speaker Byambatsogt Sandag highlighting the goals of raising trust in the legislature and adopting people-centred laws.\n\nThe Oyu Tolgoi contract amendment is seen as an important step towards increasing the benefits Mongolia receives from its largest mining project. During Mining Week and MinePro 2026, green growth and global partnerships were central themes, and Prime Minister Nyam-Osor Uchral and Minister of Industry and Mineral Resources G. Damdinnyam stressed that mineral development must deliver tangible benefits to local communities.\n\nThe European Bank for Reconstruction and Development and the Green Climate Fund have also launched a GEFF framework for greening Mongolia's financial system, aimed at expanding green finance. Amendments to the Minerals Law have reached the parliamentary approval stage and are expected to improve conditions for exploration and investment, Minister Damdinnyam said."},
  {id:11, cat:"ediin-zasag", title:"Оюутолгойн ногдол ашгийг зарцуулах төлөвлөгөөг цуцалж, мөнгийг Хуримтлалын санд шилжүүллээ", titleEn:"Oyu Tolgoi dividend vote scraps spending plan; money to go to Savings Fund", time:"10 цаг", timeEn:"10 hours ago", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Bingham_Canyon_Open_Pit_Copper_Mine_2012-09-17_21-25-59.jpg?width=760", text:"Засгийн газар аравдугаар сарын 23-нд Оюутолгойн 2027 онд хүлээгдэж буй ногдол ашгийг эрчим хүч, боловсрол зэрэг төслүүдэд зарцуулах тухай нэг удаагийн хуулийн төслийг татан авч, иргэдийн санал асуулгын дүнг хүндэтгэж буйгаа мэдэгдлээ. Засгийн газар санал асуулга аравдугаар сарын 28-нд дуусахаас өмнө арга хэмжээ авсан бөгөөд тэр үед тоологдсон 96,000 орчим саналын 55,000 нь эрүүл мэнд, боловсрол, орон сууцны дэмжлэгийг Хуримтлалын сангаар дамжуулан үзүүлэхийг сонгосон бол 24,000 нь мөнгийг хадгалахыг сонгосон байна.\n\nИнгэснээр 3 их наяд төгрөг буюу 833 сая ам.доллар орчим болох Оюутолгойн ногдол ашиг нь Рио Тинто компани баталгаажуулсны дараа шууд Хуримтлалын санд орох төлөвтэй байна. Ногдол ашиг нь өөрөө хараахан баталгаажаагүй байгаа бөгөөд компанийн шийдвэрээс хамаарна.\n\nХэрэв ногдол ашгаар төсөл санхүүжүүлэх болсон бол санал асуулгад оролцогчид эрчим хүчний салбарыг 50.6 хувиар нэгдүгээрт эрэмбэлсэн байна. Засгийн газрын шийдвэр нь иргэдийн саналыг сонсож, төрийн хөрөнгийг зарцуулахдаа олон нийтийн зөвшөөрлийг чухалчилж буйн илрэл гэж ажиглагчид үзэж байна. Гэхдээ ногдол ашгийг шууд хуримтлуулах нь ойрын хугацаанд эрчим хүч, боловсролын төслүүдэд зарцуулагдах байсан хөрөнгийг хойшлуулж байна гэсэн шүүмжлэл ч гарч байна.", textEn:"On October 23 the government withdrew its one-off law to spend Oyu Tolgoi's expected 2027 dividend on energy, education and other projects, saying it was respecting the result of the public consultation it had called on the money. The cabinet acted before the consultation closed on October 28; of about 96,000 votes counted when it acted, about 55,000 chose health, education and housing support through the Savings Fund and about 24,000 chose to save the money.\n\nThe dividend, worth around 3 trillion tugrik (about 833 million US dollars), is now expected to go directly into the Savings Fund once Rio Tinto confirms it. The dividend itself is still unconfirmed and depends on the company's decision.\n\nHad projects been funded from the dividend, respondents put energy first at 50.6 percent. Observers see the government's decision as a sign that it is listening to the public and values popular consent when spending state funds, though critics note that channelling the dividend straight into savings defers money that would have gone to energy and education projects in the near term."},
  {id:12, cat:"ediin-zasag", title:"Монгол Улсад 919,104 жуулчин ирж, 1 сая жуулчны зорилтын 91.9 хувьд хүрлээ", titleEn:"919,104 tourists visit Mongolia, reaching 91.9% of the one-million goal", time:"11 цаг", timeEn:"11 hours ago", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Ankunft_in_einem_Ger-Camp_nord%C3%B6stlich_von_Ulan_Bator%2C_Mongolei.jpg?width=760", text:"2026 оны нэгдүгээр сарын 1-нээс аравдугаар сарын 29-ний өдрийн урьдчилсан статистик мэдээллээр Монгол Улс 919,104 жуулчин хүлээн авчээ. Ингэснээр жилийн 1 сая жуулчин хүлээн авах зорилтын 91.9 хувьд хүрч, зорилт биелэхэд ердөө 80,896 жуулчин үлдлээ.\n\nМонгол Улсын Засгийн газар аялал жуулчлалыг эдийн засгийн тэргүүлэх чиглэлийн нэг болгон тодорхойлж, 2023–2028 оныг «Монголд зочлох жил» болгон зарласан билээ. Төр, хувийн хэвшил, мэргэжлийн холбоод болон салбарын нийт оролцогчид хамтран ажиллаж, олон улсын сурталчилгаа, үйлчилгээний чанарыг сайжруулахад анхаарч байна.\n\nЭнэ үзүүлэлт нь зөвхөн тоон өсөлт бус, Монгол Улсын аялал жуулчлалын салбарын хамтын ажиллагаа, өрсөлдөх чадвар өсөж буйн илрэл гэж салбарынхан үзэж байна. Жилийн эцэс хүртэл хоёр сарын хугацаа үлдсэн байгаа тул 1 сая жуулчны зорилт биелэх боломжтой гэж найдаж байна. Жуулчдын тоо нэмэгдэх нь зочид буудал, тээвэр, хоол хүнс, соёлын үйлчилгээ зэрэг салбарт ажлын байр, орлогыг нэмэгдүүлж, орон нутгийн эдийн засагт шууд нөлөөлдөг байна.", textEn:"According to preliminary statistics from January 1 to October 29, 2026, Mongolia has received 919,104 tourists. That reaches 91.9 percent of the annual goal of one million visitors, leaving just 80,896 tourists to go.\n\nThe Mongolian government has designated tourism as a priority sector of the economy and declared 2023–2028 the Years to Visit Mongolia. The state, the private sector, professional associations and all industry participants are working together to improve international promotion and service quality.\n\nIndustry observers say the figure reflects not only numerical growth but also stronger cooperation and competitiveness in Mongolia's tourism sector. With two months left in the year, there is hope the one-million goal will be met. More visitors directly support jobs and income in hotels, transport, food and cultural services and benefit local economies."},
  {id:13, cat:"sport", title:"Рашид Хан Т20 олон улсын тэмцээнд 200 викет авсан анхны бөмбөгчин боллоо", titleEn:"Rashid Khan becomes first bowler to claim 200 T20I wickets", time:"12 цаг", timeEn:"12 hours ago", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Cricket_bowling_sequence_02.jpg?width=760", text:"Афганистаны ахлагч асан Рашид Хан эрэгтэйчүүдийн Т20 олон улсын крикетэд 200 викет авсан анхны бөмбөгчин боллоо. Тэрбээр пүрэв гарагт Шаржад Зимбабветэй хийсэн хоёр дахь Т20 тоглолтын есдүгээр оверт Тадиванаше Маруманийг хоёр оноотойгоор LBW аргаар гаргаж, түүхэн амжилтад хүрсэн байна.\n\nРашид энэ амжилтад 120 дахь Т20 олон улсын тоглолтдоо хүрсэн бөгөөд дундаж нь 13.96, эдийн засгийн үзүүлэлт нь 6.13 байна. Түүний амжилтад хоёр удаа таван викет авсан тохиолдол багтаж, хамгийн сайн үзүүлэлт нь 5–3 юм. Тэрбээр хоёрдугаарт бичигдэж буй Английн Адил Рашидаас 39 викетээр илүүрхэж, тэргүүлэгчдийн жагсаалтыг итгэлтэй тэргүүлж байна.\n\nРашид нь 2025 оны аравдугаар сард Абу Дабид Бангладештэй хийсэн тоглолтод Афганистаны анхны бөмбөгчин болж нэг өдрийн олон улсын тэмцээнд 200 викет авч байсан билээ. Түүний Т20 амжилт нь орчин үеийн крикетийн хамгийн агуу эргүүлэгч бөмбөгчдийн нэг гэдгийг дахин баталж, Афганистаны крикетийн өсөлтийг дэлхийд харуулж байна.", textEn:"Former Afghanistan captain Rashid Khan has become the first bowler to claim 200 wickets in men's Twenty20 internationals. He reached the milestone on Thursday during Afghanistan's second T20 against Zimbabwe in Sharjah, trapping Tadiwanashe Marumani lbw for two in the ninth over.\n\nRashid achieved the feat in his 120th T20 international, with an average of 13.96 and an economy rate of 6.13 in the format. His record includes two five-wicket hauls, with best figures of 5–3. He sits comfortably atop the leading wicket-takers' list, 39 clear of England's Adil Rashid in second place.\n\nRashid had already become the first Afghanistan bowler to reach 200 ODI wickets, against Bangladesh in Abu Dhabi in October last year. His T20 milestone confirms his status as one of the great leg-spinners of modern cricket and showcases the rise of Afghan cricket on the world stage."},
  {id:14, cat:"sport", title:"Шинэ Зеланд Энэтхэгийг 87 оноогоор хожиж, Аршдип Сингх 150 викетэд хүрлээ", titleEn:"New Zealand beat India by 87 runs as Arshdeep Singh reaches 150 wickets", time:"13 цаг", timeEn:"13 hours ago", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Eden_Park_at_Dusk%2C_2013%2C_cropped.jpg?width=760", text:"Шинэ Зеландын крикетийн шигшээ баг Оклендын Иден Паркт болсон дөрөв дэх Т20 тоглолтод Энэтхэгийг 87 оноогоор хожлоо. Эхлээд цохиулсан Шинэ Зеланд 259/7 оноо авсан бөгөөд Гленн Филлипс ердөө 49 бөмбөгнөөс 107 оноо авч гялалзсан юм. Хариуд нь Энэтхэг 20 оверт 172/9 оноо авч чадсан байна.\n\nТоглолтод Энэтхэгийн хурдан бөмбөгчин Аршдип Сингх түүх бүтээж, Т20 олон улсын тэмцээнд 150 викет авсан Энэтхэгийн анхны бөмбөгчин боллоо. Тэрбээр төгсгөлийн өмнөх оверт Шинэ Зеландын ахлагч Митчелл Сантнерыг гаргаж, 103 тоглолт, 99 иннингст 150 викетэд хүрсэн бөгөөд дундаж нь 20.62, эдийн засгийн үзүүлэлт нь 8.65, хамгийн сайн үзүүлэлт нь 5/51 юм.\n\nАршдип нь 2,143 бөмбөгөөр 150 викетэд хүрч, энэ үзүүлэлтээр Ванинду Хасаранга (2,035), Рашид Хан (2,098) нарын дараа гуравдугаарт бичигдэж байна. Мөн тэрбээр 2026 онд 40 викет авч, бүтэн гишүүн орны бөмбөгчний нэг жилийн дээд амжилтыг шинэчилсэн юм. Энэтхэг таван тоглолттой цувралыг 3–1-ээр тэргүүлж байгаа бөгөөд сүүлийн тоглолт арваннэгдүгээр сарын 1-нд Хэмилтонд болно.", textEn:"New Zealand beat India by 87 runs in the fourth T20I at Eden Park in Auckland. Batting first, New Zealand posted 259/7, with Glenn Phillips smashing 107 off just 49 balls, before India managed 172/9 in their 20 overs.\n\nThe match also saw India pacer Arshdeep Singh make history, becoming the first Indian bowler to take 150 wickets in T20 internationals. He dismissed New Zealand captain Mitchell Santner in the penultimate over to reach 150 wickets in 103 matches and 99 innings, at an average of 20.62 and an economy rate of 8.65, with best figures of 5/51.\n\nArshdeep reached the mark in 2,143 balls, the third-fastest behind Wanindu Hasaranga (2,035) and Rashid Khan (2,098). He has also taken 40 wickets in 2026, a new calendar-year record for a bowler representing a Full Member nation. India still lead the five-match series 3–1, with the final T20I in Hamilton on November 1."},
  {id:15, cat:"soyol", title:"«Оддын аялал», «X-Men»-ийн од Патрик Стюарт 86 насандаа таалал төгслөө", titleEn:"Star Trek and X-Men star Patrick Stewart dies at 86", time:"14 цаг", timeEn:"14 hours ago", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Adam_Scott%2C_Horace_Newcomb%2C_and_Patrick_Stewart%2C_May_2012.jpg?width=760", text:"Английн жүжигчин, «Оддын аялал: Дараагийн үе» цувралын ахмад Жан-Люк Пикард, «X-Men» кинонуудын профессор Чарльз Ксавьегийн дүрээрээ алдаршсан Патрик Стюарт 86 насандаа таалал төгслөө. Түүний хэвлэлийн төлөөлөгч Келли Буш Новак мэдэгдсэнээр, Стюарт лхагва гарагт Лос-Анжелес дахь гэртээ, хайртай эхнэр Саннигийнхаа асрамжинд, Альцгеймер болон Льюи биетийн дементитэй «товч бөгөөд сэтгэл шимшрэм» тэмцлийн дараа нас баржээ. Эдгээр онош нь өмнө нь олон нийтэд мэдэгдээгүй байв.\n\nСтюарт 18 настайдаа жүжигчин болж, 1960-аад оноос Хааны Шекспирийн компанийн гишүүн болж тайзнаа нэр хүнд олсон юм. Гэхдээ дэлхийд алдарших нь 47 настайдаа «Оддын аялал: Дараагийн үе» (1987–1994) цувралд тоглосноор ирсэн бөгөөд тэрбээр долоон улирал, 176 анги, дөрвөн кинонд Пикардын дүрийг бүтээж, 2020–2023 онд «Оддын аялал: Пикард» цувралд эргэн ирсэн билээ. 2000 оноос эхлэн «X-Men» франчайзад профессор Икс гэдгээрээ 20 гаруй жил тоглож, Марвелийн хамгийн урт карьерийн Гиннесийн дээд амжилтыг тогтоосон байна.\n\n2010 онд II Элизабет хатан хаан түүнийг драмын урлагт оруулсан хувь нэмрийг нь үнэлж, хүлэг цол олгосон юм. Түүний үхлийн мэдээ гарсны дараа Иэн Маккеллен, Хью Жекман, Уильям Шатнер, ЛеВар Бёртон, Жонатан Фрейкс зэрэг хамтран тоглогчид нь түүнийг багш, найз, хүнлэг сэтгэлтэй уран бүтээлч байсан гэж дурсан хүндэтгэл үзүүлж байна. Стюарт эхнэр Санни Озелл болон анхны гэрлэлтээсээ төрсөн хоёр хүүхэд болох Даниэль, Софи нарыг үлдээжээ.", textEn:"Patrick Stewart, the English actor beloved as Captain Jean-Luc Picard in Star Trek: The Next Generation and Professor Charles Xavier in the X-Men films, has died at the age of 86. His spokesperson Kelly Bush Novak said Stewart died on Wednesday at his home in Los Angeles, in the loving care of his wife Sunny, following a brief and poignant journey with Alzheimer's disease and Lewy body dementia. Neither diagnosis had previously been publicly disclosed.\n\nStewart became an actor at 18 and gained acclaim on stage as a member of the Royal Shakespeare Company from the 1960s. Mainstream fame came when he was hired at 47 for Star Trek: The Next Generation (1987–1994), playing Picard across seven seasons, 176 episodes and four films, and returning in the series Star Trek: Picard (2020–2023). From 2000 he played Professor X in the X-Men franchise for more than two decades, setting the Guinness World Record for the longest Marvel career.\n\nHe was knighted by Queen Elizabeth II in 2010 for services to drama. Following the announcement, co-stars including Ian McKellen, Hugh Jackman, William Shatner, LeVar Burton and Jonathan Frakes paid tribute, remembering him as a mentor, a friend and a humane artist. Stewart is survived by his wife Sunny Ozell and two children, Daniel and Sophie, from his first marriage."},
  {id:16, cat:"soyol", title:"«Улаанбаатар» пянз: 11 дуу багтсан хотын соёлын өвийн цомог бүтээгдлээ", titleEn:"Ulaanbaatar vinyl album celebrates the city's heritage with 11 songs", time:"15 цаг", timeEn:"15 hours ago", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Groove_and_needle_in_close_embrace_from_beginning_to_end.jpg?width=760", text:"Нийслэлийн соёл, урлагийн өвийг түгээн дэлгэрүүлэх, хотын түүх, онцлог, өнгө төрхийг илэрхийлсэн бүтээлүүдийг олон нийтэд хүргэх зорилгоор «Улаанбаатар» пянзыг Нийслэлийн Засаг даргын Тамгын газрын дэмжлэгтэйгээр бүтээжээ. Пянзны нээлтийн ёслол аравдугаар сарын 30-ны 11:40 цагт Улаанбаатар театрын үзэсгэлэнгийн танхимд болсон байна.\n\nПянзанд «Миний Улаанбаатар», «Дөрвөн уул», «Үйлсийн сайхан Улаанбаатар», «Улаанбаатарын тухай дуу», «Улаанбаатарын үдэш», «Ай наанаа», «Айсуй хүлгийн төвөргөөн» зэрэг нийт 11 хөгжмийн бүтээл багтжээ. Улаанбаатар театр үүсэн байгуулагдсаны 20 жилийн ой, нийслэл хотын 387 жилийн ойд зориулан бүтээсэн энэ пянз нь «Авьяасаар бүтээсэн 20 жил» уриан дор хийгдсэн байна.\n\n«Улаанбаатар театр» ОНӨТҮГ-ын дарга, урлагийн гавьяат зүтгэлтэн Д.Ариунбаатар пянз нь нийслэл хотынхоо соёл, урлагийн өвийг дуу хөгжмөөр дамжуулан мөнхөлж, хойч үедээ өвлүүлэн үлдээх зорилготой гэж онцоллоо. Пянз нь «Улаанбаатар» соёлын брэндийг бий болгох, хотынхоо дуу хөгжмийн өвийг түгээн дэлгэрүүлэх алхам гэж зохион байгуулагчид үзэж байна.", textEn:"A vinyl album titled Ulaanbaatar has been produced with the support of the Ulaanbaatar City Governor's Office, aiming to promote the capital's cultural heritage and share works that express the city's history and character with the public. The album's launch ceremony took place at 11:40 a.m. on October 30 at the Ulaanbaatar Theatre's exhibition hall.\n\nThe album features 11 musical works, including My Ulaanbaatar, Four Mountains, Beautiful Ulaanbaatar of Deeds, Song about Ulaanbaatar, Ulaanbaatar Evening, Ai Naanaa and Aisui Khulgiin Tovorgon. It was created for the 20th anniversary of the Ulaanbaatar Theatre and the 387th anniversary of the capital, under the slogan Twenty Years Created with Talent.\n\nD. Ariunbaatar, director of the Ulaanbaatar Theatre and a Merited Artist, stressed that the album aims to immortalise the city's cultural heritage through song and pass it on to future generations. Organisers see the album as a step towards building the Ulaanbaatar cultural brand and spreading the city's musical heritage."},
  {id:17, cat:"tech", title:"Хойд Солонгосын хакеруудыг Binance-ийн 6.3 тэрбум ам.долларын хулгайд буруутгаж байна", titleEn:"North Korean hackers blamed for $6.3 billion Binance crypto heist", time:"16 цаг", timeEn:"16 hours ago", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Bitcoin_on_Laptop_Keyboard.jpg?width=760", text:"Хойд Солонгосын хакеруудыг Binance крипто биржээс 6.3 тэрбум ам.доллар хулгайлсан хэрэгт буруутгаж байгаа бөгөөд энэ нь дэлхийн хамгийн том крипто хулгай гэж нэрлэгдэж байна. Хэрэв энэ хэмжээ баталгаажвал өмнөх бүх крипто хулгайн дээд амжилтыг хол давж, дижитал хөрөнгийн аюулгүй байдлын талаарх маргааныг дахин хурцатгах болно.\n\nКрипто биржүүд нь хакеруудын байнгын бай болсоор ирсэн бөгөөд томоохон хулгай бүр нь биржүүдийн хамгаалалт, хэрэглэгчийн хөрөнгийг хадгалах арга, зохицуулалтын хяналтын талаар асуултуудыг дагуулдаг. Хойд Солонгосын хакерын бүлгүүдийг өмнө нь ч олон улсын мөрдөн шалгах байгууллагууд томоохон крипто хулгайтай холбон нэрлэж байсан бөгөөд хулгайлсан хөрөнгийг дэглэмийн зэвсгийн хөтөлбөрт зарцуулдаг гэж үздэг.\n\nBinance нь дэлхийн хамгийн том крипто биржүүдийн нэг бөгөөд энэ хэргийн цар хүрээ нь хэрэглэгчид болон зах зээлд итгэх итгэлд шууд нөлөөлж болзошгүй байна. Мөрдөн шалгах ажиллагаа үргэлжилж байгаа бөгөөд хулгайлсан хөрөнгийг мөрдөх, царцаах, нөхөн сэргээх чиглэлээр бирж, эрх баригчид хамтран ажиллаж байна гэж мэдээлж байна. Крипто салбарынхан энэ явдлыг аюулгүй байдлын стандартыг чангатгах шаардлагатайг харуулсан сэрэмжлүүлэг гэж үзэж байна.", textEn:"North Korean hackers have been blamed for a $6.3 billion crypto heist from the Binance exchange, described as the world's biggest theft. If the figure is confirmed, it would far exceed all previous crypto theft records and reignite debate about the security of digital assets.\n\nCrypto exchanges have long been targets for hackers, and every major theft raises questions about exchange security, how customer funds are stored and regulatory oversight. North Korean hacking groups have previously been linked by international investigators to major crypto thefts, with stolen funds allegedly used to finance the regime's weapons programmes.\n\nBinance is one of the world's largest crypto exchanges, and the scale of the incident could directly affect user and market confidence. Investigations are continuing, with the exchange and authorities reportedly working together to trace, freeze and recover the stolen funds. Industry figures see the incident as a warning that security standards need to be tightened."},
  {id:18, cat:"oron-nutag", region:"zavkhan", title:"Увс, Завханы зарим сумдад 20–50 см цас тогтож, шөнөдөө -32 хэм хүрч хүйтэрлээ", titleEn:"Snow reaches 20–50 cm in Uvs and Zavkhan, with nights down to minus 32 degrees", time:"Өчигдөр", timeEn:"Yesterday", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Snow_in_Mongolia_(MODIS_2017-01-19).jpg?width=760", text:"Хөдөө аж ахуйн цаг уурын арав хоногийн тоймоор 2026 оны аравдугаар сарын 20-ны байдлаар нийт нутгийн 20 орчим хувьд цастай байгаа бөгөөд Увсын Наранбулаг, Малчин, Өмнөговь, Өндөрхангай, Хяргас, Завханы Идэрт 20–50 см зузаан цастай байна. Хамгийн их нь Увсын Наранбулагт 50 см цас орсон байна.\n\nМөн Увсын Ховд, Түргэн, Зүүнхангай, Завхан, Баруунтуруун, Завханы Яруу, Цэцэн-Уул, Цагаанчулуут, Цагаанхайрхан, Тэс, Түдэвтэй, Их-Уул, Хөвсгөлийн Цагаан-Уул, Улаан-Уул, Рашаант, Жаргалант, Арбулаг, Архангайн Жаргалантад 10–18 см цас тогтсон бол Баян-Өлгий, Ховдын ихэнх, Увс, Завхан, Хөвсгөлийн зарим, Архангай, Булган, Говь-Алтай, Дархан-Уул, Сэлэнгэ, Өвөрхангайн цөөн, Баянхонгор, Улаанбаатар, Орхон, Төв, Өмнөговийн ганц нэг сумдаар 1–9 см цас байна.\n\nӨнгөрсөн арав хоногт агаарын температур зүүн аймгуудын нийт нутгаар олон жилийн дунджийн орчим болон түүнээс 1.1–1.2 хэмээр дулаан, бусад нутгаар 1.1–5.9 хэмээр хүйтэн байлаа. Ихэнх нутгаар хүйтэрч, Завханы Яруу, Цэцэн-Уул, Отгон, Идэр, Ховдын Дуут сумдад шөнөдөө -25...-32 хэм хүрч хүйтэрсэн байна. Салхины хурд Төвийн Баянжаргалан, Баянхонгорын Богд, Өмнөговийн Цогт-Овоо, Дорноговийн Сайншандад 24–25 м/с буюу аюултай үзэгдэл, Архангай Хотонтод 30 м/с буюу гамшигт үзэгдлийн хэмжээнд хүрч салхилсан байна.", textEn:"According to the 10-day agrometeorological review, as of October 20, 2026, about 20 percent of Mongolia's territory is snow-covered, with snow 20–50 cm deep in Uvs province's Narantbulag, Malchin, Umnugovi, Undurkhangai and Khyargas sums and Zavkhan province's Ider sum. The deepest snow, 50 cm, was recorded in Narantbulag, Uvs.\n\nSnow of 10–18 cm has also settled in Uvs's Khovd, Turgen, Zuunkhangai, Zavkhan and Baruunturuun sums, Zavkhan's Yaru, Tsetsen-Uul, Tsagaanchuluut, Tsagaankhairkhan, Tes, Tudevtei and Ikh-Uul, Khuvsgul's Tsagaan-Uul, Ulaan-Uul, Rashaan, Jargalant and Arbulag, and Arkhangai's Jargalant, while 1–9 cm was recorded in scattered sums of Bayan-Ulgii, Khovd, Uvs, Zavkhan, Khuvsgul, Arkhangai, Bulgan, Govi-Altai, Darkhan-Uul, Selenge, Uvurkhangai, Bayankhongor, Ulaanbaatar, Orkhon, Tuv and Umnugovi.\n\nOver the past 10 days, temperatures in the eastern provinces were around or 1.1–1.2 degrees above the long-term average, while elsewhere they were 1.1–5.9 degrees below average. It turned colder across most of the country, with nights reaching minus 25 to minus 32 degrees in Zavkhan's Yaru, Tsetsen-Uul, Otgon and Ider and Khovd's Duut sums. Wind speeds reached 24–25 metres per second, a dangerous level, in Tuv's Bayanjargalan, Bayankhongor's Bogd, Umnugovi's Tsogt-Ovoo and Dornogovi's Sainshand, and 30 metres per second, a disaster level, in Arkhangai's Khotont."}
];
function aTitle(a){ return LANG === "en" ? (a.titleEn || a.title) : a.title; }
function aTime(a){ return LANG === "en" ? (a.timeEn || a.time) : a.time; }
function aText(a){ if(a.text) return LANG === "en" ? (a.textEn || a.text) : a.text; return SAMPLE_TEXT[LANG][a.id === 1 ? "long" : "short"]; }
function aRegion(a){ return a.region ? ((REGIONS[LANG] && REGIONS[LANG][a.region]) || a.region) : ""; }

// ===== Ханш · Цаг агаар (өдөр бүр шинэчлэгдэнэ; цаг агаарыг Open-Meteo-гоос шууд татна) =====
const RATES = {date:"2026-10-31", items:[
  {code:"USD", mnt:3599.28, chg:1}, {code:"EUR", mnt:4027.77, chg:1}, {code:"JPY", mnt:22.84, chg:1},
  {code:"CNY", mnt:540.76, chg:1}, {code:"KRW", mnt:2.70, chg:1}, {code:"RUB", mnt:44.61, chg:1}, {code:"GBP", mnt:4824.47, chg:1}
]};
let WEATHER = [
  {city:"Улаанбаатар", cityEn:"Ulaanbaatar", lat:47.9212, lon:106.9186, tz:"Asia/Ulaanbaatar", temp:-7, code:1},
  {city:"Токио", cityEn:"Tokyo", lat:35.6762, lon:139.6503, tz:"Asia/Tokyo", temp:20, code:1},
  {city:"Сөүл", cityEn:"Seoul", lat:37.5665, lon:126.978, tz:"Asia/Seoul", temp:15, code:0},
  {city:"Бээжин", cityEn:"Beijing", lat:39.9042, lon:116.4074, tz:"Asia/Shanghai", temp:16, code:0},
  {city:"Москва", cityEn:"Moscow", lat:55.7558, lon:37.6173, tz:"Europe/Moscow", temp:5, code:3}
];
function wIcon(code){
  if(code === 0) return "☀️";
  if(code === 1) return "🌤️";
  if(code === 2) return "⛅";
  if(code === 3) return "☁️";
  if(code === 45 || code === 48) return "🌫️";
  if(code === 51 || code === 53 || code === 55 || code === 80) return "🌦️";
  if(code === 56 || code === 57 || code === 61 || code === 63 || code === 65 || code === 66 || code === 67 || code === 81 || code === 82) return "🌧️";
  if(code === 71 || code === 73 || code === 75 || code === 77 || code === 85 || code === 86) return "❄️";
  if(code >= 95) return "⛈️";
  return "🌡️";
}
function fmtRate(v){
  if(v >= 100) return Math.round(v).toLocaleString("en-US");
  return v.toFixed(2);
}
function renderData(){
  const parts = [];
  RATES.items.forEach(r=>{
    let arrow = "";
    if(r.chg > 0) arrow = ' <span class="up">▲</span>';
    else if(r.chg < 0) arrow = ' <span class="down">▼</span>';
    parts.push(`<span class="tk"><b>${r.code}</b> ${fmtRate(r.mnt)}₮${arrow}</span>`);
  });
  WEATHER.forEach(w=>{
    const name = LANG === "en" ? w.cityEn : w.city;
    const t = w.temp > 0 ? "+" + w.temp : "" + w.temp;
    parts.push(`<span class="tk">${wIcon(w.code)} ${name} ${t}°C</span>`);
  });
  const html = parts.join('<span style="color:#666">•</span>');
  const track = document.getElementById("tickerTrack");
  if(track) track.innerHTML = html + '<span style="color:#666">•</span>' + html + '<span style="color:#666">•</span>';
  const usd = RATES.items.find(r=>r.code === "USD");
  const ue = document.getElementById("usdText");
  if(ue && usd) ue.textContent = "USD: " + fmtRate(usd.mnt) + "₮";
  const wt = document.getElementById("weatherText");
  const ub = WEATHER[0];
  if(wt && ub) wt.textContent = wIcon(ub.code) + " " + (LANG === "en" ? ub.cityEn : ub.city) + " " + (ub.temp > 0 ? "+" + ub.temp : ub.temp) + "°C";
}
function refreshWeather(){
  WEATHER.forEach((w, idx)=>{
    const url = "https://api.open-meteo.com/v1/forecast?latitude=" + w.lat + "&longitude=" + w.lon + "&current=temperature_2m%2Cweather_code&timezone=" + encodeURIComponent(w.tz);
    fetch(url).then(r=>r.json()).then(d=>{
      if(d && d.current){ WEATHER[idx].temp = Math.round(d.current.temperature_2m); WEATHER[idx].code = d.current.weather_code; renderData(); }
    }).catch(()=>{});
  });
}

